create or replace function public.ils_professional_can_access_work(p_work_item_id uuid, p_work_stream text, p_user_id uuid) returns boolean language sql security definer stable set search_path = public as $$ select case when p_user_id is null or auth.uid() is null or auth.uid() <> p_user_id then false when p_work_stream='PROFESSIONAL' then exists (select 1 from public.ils_professional_work_items w join public.ils_professional_work_assignment_links l on l.work_item_id=w.id and l.work_stream='PROFESSIONAL' and l.professional_user_id=w.professional_user_id and l.link_status='APPROVED' join public.ils_unified_assignment_decisions u on u.id=l.assignment_decision_id and u.associate_user_id=w.professional_user_id and u.decision='ALLOW' where w.id=p_work_item_id and w.professional_user_id=p_user_id) when p_work_stream='B2B' then exists (select 1 from public.ils_b2b_work_items w join public.ils_professional_work_assignment_links l on l.work_item_id=w.id and l.work_stream='B2B' and l.professional_user_id=w.professional_user_id and l.link_status='APPROVED' join public.ils_unified_assignment_decisions u on u.id=l.assignment_decision_id and u.associate_user_id=w.professional_user_id and u.decision='ALLOW' where w.id=p_work_item_id and w.professional_user_id=p_user_id) else false end $$;
revoke all on function public.ils_professional_can_access_work(uuid,text,uuid) from public,anon,authenticated;
grant execute on function public.ils_professional_can_access_work(uuid,text,uuid) to authenticated;
create policy professional_own_assigned_work_select on public.ils_professional_work_items for select to authenticated using (public.ils_professional_can_access_work(id,'PROFESSIONAL',professional_user_id));
create policy b2b_own_assigned_work_select on public.ils_b2b_work_items for select to authenticated using (public.ils_professional_can_access_work(id,'B2B',professional_user_id));
create policy professional_own_assigned_events_select on public.ils_professional_work_events for select to authenticated using (exists (select 1 from public.ils_professional_work_items w where w.id=ils_professional_work_events.work_item_id and public.ils_professional_can_access_work(w.id,'PROFESSIONAL',w.professional_user_id)));
create policy b2b_own_assigned_events_select on public.ils_b2b_work_events for select to authenticated using (exists (select 1 from public.ils_b2b_work_items w where w.id=ils_b2b_work_events.work_item_id and public.ils_professional_can_access_work(w.id,'B2B',w.professional_user_id)));
comment on function public.ils_professional_can_access_work(uuid,text,uuid) is 'ACTION 468 fail-closed professional assignment boundary; requires authenticated self, approved identity bridge, and ALLOW unified assignment decision.';